 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    ups = downs = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and grid[p[0]][p[1]] == 2 and p not in seen:
                        seen.add(p)
                        stack.append(p)
            if len(cells) != 4:
                continue
            minr, maxr = min(y for y, x in cells), max(y for y, x in cells)
            minc, maxc = min(x for y, x in cells), max(x for y, x in cells)
            local = {(y - minr, x - minc) for y, x in cells}
            if (maxr - minr, maxc - minc) != (1, 2):
                continue
            if local == {(0, 1), (1, 0), (1, 1), (1, 2)}:
                ups += 1
            elif local == {(0, 0), (0, 1), (0, 2), (1, 1)}:
                downs += 1
    out = [[0] * 6 for _ in range(3)]
    slots = ((0, 0), (2, 0), (0, 2), (2, 2))
    for count, color, offset in ((ups, 3, 0), (downs, 1, 3)):
        for r, c in slots[:min(count, 4)]:
            out[r][c + offset] = color
    return out
